UPDATE item_template i JOIN dc_base_item b ON b.entry=i.entry SET i.Flags=i.Flags|134217728, i.ItemLevel=70;
CREATE TEMPORARY TABLE dc_native_durability AS SELECT class,InventoryType,MAX(MaxDurability) durability FROM item_template WHERE entry<100000 AND ItemLevel BETWEEN 60 AND 70 GROUP BY class,InventoryType;
UPDATE item_template i JOIN dc_base_item b ON b.entry=i.entry JOIN dc_native_durability d ON d.class=i.class AND d.InventoryType=i.InventoryType SET i.MaxDurability=d.durability;
DROP TEMPORARY TABLE dc_native_durability;
