UPDATE dc_gem_template SET entry=103049,name='Star Topaz',class=7,subclass=4,Quality=3,Flags=0,FlagsExtra=0,ItemLevel=70,RequiredLevel=0,bonding=0,stackable=200,BuyPrice=0,SellPrice=0,GemProperties=0,stat_type1=0,stat_value1=0,stat_type2=0,stat_value2=0,stat_type3=0,stat_value3=0,stat_type4=0,stat_value4=0,stat_type5=0,stat_value5=0,stat_type6=0,stat_value6=0,stat_type7=0,stat_value7=0,stat_type8=0,stat_value8=0,stat_type9=0,stat_value9=0,stat_type10=0,stat_value10=0,spellid_1=0,spellid_2=0,spellid_3=0,spellid_4=0,spellid_5=0;
