DROP TABLE IF EXISTS `dc_set_tooltip`;
CREATE TABLE `dc_set_tooltip` (set_id VARCHAR(80) PRIMARY KEY,name VARCHAR(160),bonuses LONGTEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `dc_set_tooltip` VALUES ('chantodo','Chantodo''s Resolve','{"2": [{"format": "Every second while in Archon form you expel a Wave of Destruction, dealing 4000%% weapon damage to enemies within 30 yards. This damage scales with attack speed."}, {"format": "Every time you hit with an attack while not in Archon form, 4000%% weapon damage is added to the Wave of Destruction, stacking up to 20 times."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('danetta','Danetta''s Hatred','{"2": [{"format": "Vault costs 8 Hatred instead of Discipline."}, {"format": "Vault deals 800%% increased damage."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('blackthorne','Blackthorne''s Battlegear','{"2": [{"stat": "vit", "value": [250]}, {"stat": "edmg", "value": [10]}], "3": [{"stat": "edef", "value": [10]}, {"stat": "gf", "value": [25]}], "4": [{"format": "You are immune to Desecrator, Molten, and Plagued monster ground effects."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('bulkathos','Bul-Kathos''s Oath','{"2": [{"stat": "furyregen", "value": [15]}, {"format": "During Whirlwind gain 45%% increased Attack Speed and Movement Speed."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('endlesswalk','Endless Walk','{"2": [{"format": "While moving, damage taken is reduced by up to 50%%."}, {"format": "While standing still, damage dealt is increased by up to 100%%."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('nightmares','Legacy of Nightmares','{"2": [{"format": "While this is your only Item Set bonus every Ancient item you have equipped increases your damage dealt by 750%% and reduces your damage taken by 4%%."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('manajuma','Manajuma''s Way','{"2": [{"format": "Your Hex - Angry Chicken explosion damage is increased by 2000%% and slain enemies trigger an additional explosion."}, {"format": "While you are an angry chicken, you spawn a chicken every half second that seeks enemies and deals 100%% of your Angry Chicken explosion damage."}, {"format": "Your Hex - Angry Chicken lasts 15 seconds and movement speed is increased by an additional 100%% while gaining 75%% damage reduction. These bonuses lasts while you are a chicken and for 5 seconds after."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('shenlong','Shenlong''s Spirit','{"2": [{"format": "The damage of your Spirit Generators is increased by 2%% for each point of Spirit you have."}, {"format": "When reaching maximum Spirit, all damage is increased by 350%%, but you no longer passively regenerate Spirit and 65 Spirit is drained every second until you run out of Spirit."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('bastionsofwill','Bastions of Will','{"2": [{"format": "When you hit with a resource-generating attack or primary skill, deal 50%% increased damage for 5 seconds."}, {"format": "When you hit with a resource-spending attack, deal 50%% increased damage for 5 seconds."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('istvan','Istvan''s Paired Blades','{"2": [{"format": "Every time you spend primary resource, gain 6%% increased Attack Speed, Damage, and Armor for 5 seconds. This effect stacks up to 5 times."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('invoker','Thorns of the Invoker','{"2": [{"format": "Your Thorns damage now hits all enemies in a 15 yard radius around you. Each time you hit an enemy with Punish, Slash, or block an attack your Thorns is increased by 90%% for 2 seconds. This effect stacks up to 10 times."}], "4": [{"format": "You take 50%% less damage for 20 seconds after damaging an enemy with Bombardment."}], "6": [{"format": "The attack speed of Punish and Slash are increased by 100%% and deal 67500%% of your Thorns damage."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('krelm','Krelm’s Buff Bulwark','{"2": [{"stat": "vit", "value": [500]}]}');
INSERT INTO `dc_set_tooltip` VALUES ('asheara','Asheara''s Vestments','{"2": [{"stat": "resall", "value": [100]}], "3": [{"stat": "life", "value": [20]}], "4": [{"format": "Attacks cause your followers to occasionally come to your aid."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('aughild','Aughild''s Authority','{"2": [{"stat": "rangedef", "value": [7]}, {"stat": "meleedef", "value": [7]}], "3": [{"stat": "edef", "value": [15]}, {"stat": "edmg", "value": [15]}]}');
INSERT INTO `dc_set_tooltip` VALUES ('born','Born''s Command','{"2": [{"stat": "life", "value": [15]}], "3": [{"stat": "cdr", "value": [10]}, {"stat": "expmul", "value": [20]}]}');
INSERT INTO `dc_set_tooltip` VALUES ('cain','Cain''s Destiny','{"2": [{"stat": "ias", "value": [8]}], "3": [{"stat": "mf", "value": [50]}, {"stat": "expmul", "value": [50]}]}');
INSERT INTO `dc_set_tooltip` VALUES ('crimson','Captain Crimson''s Trimmings','{"2": [{"stat": "regen", "value": [6000]}, {"stat": "cdr", "value": [10]}], "3": [{"stat": "resall", "value": [50]}, {"stat": "rcr", "value": [10]}]}');
INSERT INTO `dc_set_tooltip` VALUES ('demon','Demon''s Hide','{"2": [{"stat": "firethorns", "value": [6000]}], "3": [{"stat": "area", "value": [25]}], "4": [{"stat": "damage_demons", "value": [15]}, {"format": "Chance to reflect projectiles when you are hit by enemies."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('guardian','Guardian''s Jeopardy','{"2": [{"stat": "vit", "value": [250]}, {"stat": "regen", "value": [8000]}], "3": [{"stat": "ms", "value": [15]}]}');
INSERT INTO `dc_set_tooltip` VALUES ('hallowed','Hallowed Protectors','{"2": [{"stat": "resall", "value": [100]}, {"stat": "ias", "value": [10]}]}');
INSERT INTO `dc_set_tooltip` VALUES ('sage','Sage''s Journey','{"2": [{"stat": "str", "value": [250]}, {"stat": "dex", "value": [250]}, {"stat": "int", "value": [250]}, {"stat": "vit", "value": [250]}], "3": [{"format": "Double the amount of Death''s Breath that drop. (Emanates)", "follower": true}]}');
INSERT INTO `dc_set_tooltip` VALUES ('talrasha','Tal Rasha''s Elements','{"2": [{"format": "Damaging enemies with Arcane, Cold, Fire or Lightning will grant immunity to that element and cause a Meteor of the same damage type to fall from the sky. This only occurs if the Wizard has Meteor on their action bar, and the same meteor cannot happen twice in a row."}], "4": [{"format": "Arcane, Cold, Fire, and Lightning attacks each increase all of your resistances by 100%% for 8 seconds. Attacking with Meteor reduces the cooldown of Teleport by 1 second."}], "6": [{"format": "Attacks increase your damage by 1000%% for 8 seconds. Arcane, Cold, Fire, and Lightning attacks each add one stack. At 4 stacks, each different elemental attack extends the duration by 2 seconds, up to a maximum of 8 seconds."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('vyr','Vyr''s Amazing Arcana','{"2": [{"format": "Archon gains the effect of every rune."}], "4": [{"format": "Archon stacks also increase your Attack Speed, Armor, and Resistances by 1%%."}], "6": [{"format": "You gain 1 Archon stack when you hit with an Archon ability and Archon stacks also reduce damage taken by 0.15%% and have their damage bonus increased to 100%%."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('firebird','Firebird''s Finery','{"2": [{"format": "Disintegrate Ignites enemies, causing them to take 3000%% weapon damage per second until they die. When you die, a meteor falls from the sky and revives you. This effect has a 60 second cooldown."}], "4": [{"format": "Casting Disintegrate adds Combustion stacks that reduce the cooldown of Teleport by 2%% per stack. Stacks up to 50 times. You gain 80%% damage reduction while maintaining Combustion stacks."}], "6": [{"format": "You gain 5000%% increased damage while Ignite is applied to a target. Hitting an Ignited enemy with a non-channeling fire spell deals Ignite damage multiplied by Combustion stacks. Pets cannot trigger this effect."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('natalya','Natalya''s Vengeance','{"2": [{"format": "Spike Trap deals 100%% increased damage to enemies affected by Caltrops. Spike Trap now instantly refreshes charges on use, no longer costs resources, and each detonation restores 2 Discipline."}], "4": [{"format": "Spike Trap explosions will blast affected enemies towards the nearest set Caltrops. Laying a Spike Trap grants 75%% damage reduction. The duration of this bonus is always equal to the number of already laid traps in seconds."}], "6": [{"format": "Spike Trap deals 10000%% increased damage, and each consecutive explosion from the detonated chain reaction will deal 25%% more damage than the previous blast."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('shadow','The Shadow’s Mantle','{"2": [{"format": "While equipped with a melee weapon, the damage of your Bolas, Chakram, Fan of Knives, and Impale is increased by 6000%%."}], "4": [{"format": "Shadow Power gains the effect of every rune and lasts forever."}], "6": [{"format": "Impale deals an additional 120000%% weapon damage to the first enemy hit, and 40000%% to subsequent enemies."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('marauder','Embodiment of the Marauder','{"2": [{"format": "Companion calls all companion types to your side."}], "4": [{"format": "Sentries cast Elemental Arrow, Chakram, Impale, Multishot, and Cluster Arrow when you do, as well as automatically cast your equipped Hatred spenders."}], "6": [{"format": "Your primary skills, Elemental Arrow, Chakram, Impale, Multishot, Cluster Arrow, Companions, Vengeance and Sentries deal 9500%% increased damage for every active Sentry."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('zunimassa','Zunimassa''s Haunt','{"2": [{"format": "Your Fetish Army lasts until they die and the cooldown of your Fetish Army is reduced by 80%."}], "4": [{"format": "You and your pets take 3% less damage for every Fetish you have alive."}], "6": [{"format": "Enemies hit by your Mana spenders take 13000%% more damage from your pets for 8 seconds."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('helltooth','Helltooth Harness','{"2": [{"format": "Enemies hit by your primary skills, Acid Cloud, Firebats, Zombie Charger, Zombie Dogs, Gargantuan, Grasp of the Dead, Piranhas, or Wall of Death are afflicted by Necrosis, becoming Slowed and taking 3000%% weapon damage every second for 10 seconds."}], "4": [{"format": "After applying Necrosis to an enemy, you take 60%% reduced damage for 10 seconds."}], "6": [{"format": "After casting Wall of Death, gain 37500%% increased damage for 15 seconds to your primary skills, Acid Cloud, Firebats, Zombie Charger, Zombie Dogs, Gargantuan, Grasp of the Dead, Piranhas, and Wall of Death."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('jadeharvester','Raiment of the Jade Harvester','{"2": [{"format": "When Haunt lands on an enemy already affected by Haunt, it instantly deals 3500 seconds worth of Haunt damage."}], "4": [{"format": "Soul Harvest gains the effect of every rune and has its cooldown reduced by 1 second every time you cast Haunt or Locust Swarm."}], "6": [{"format": "Soul Harvest reduces damage taken by 50%% for 12 seconds and consumes your damage over time effects on enemies, instantly dealing 26,000 seconds worth of remaining damage."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('immortalking','Immortal King''s Call','{"2": [{"format": "Call of the Ancients last until they die."}], "4": [{"format": "Reduce the cooldown of Wrath of the Berserker and Call of the Ancients by 3 seconds for every 10 Fury you spend with an attack."}], "6": [{"format": "While both Wrath of the Berserker and Call of the Ancients are active, you deal 4000%% increased damage."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('earth','Might of the Earth','{"2": [{"format": "Reduce the cooldown of Earthquake, Avalanche, Leap, and Ground Stomp by 1 second for every 30 Fury you spend with an attack."}], "4": [{"format": "Leap causes an Earthquake when you land. Additionally, Leap gains the effect of the Iron Impact rune and the rune''s effect and duration are increased by 150%%."}], "6": [{"format": "Increase the damage of Earthquake, Avalanche, Leap, Ground Stomp, Ancient Spear and Seismic Slam by 37500%%."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('raekor','The Legacy of Raekor','{"2": [{"format": "Furious Charge refunds a charge if it hits only 1 enemy."}], "4": [{"format": "Furious Charge gains the effect of every rune and deals 1000%% increased damage. For every 1%% Life you are missing, the damage of your Ancient Spear is increased by 2%%."}], "6": [{"format": "Hitting enemies with Furious Charge or Weapon Throw increases the damage of your next Ancient Spear by 2500%% and causes it to release multiple spears from its target. This effect stacks and each spear throw consumes a maximum of 5 stacks."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('inna','Inna''s Mantra','{"2": [{"format": "Increase the passive effect of your Mystic Ally and the base passive effect of your Mantra by 100%%."}], "4": [{"format": "Gain the base effect of all four Mantras at all times. You gain 5% damage reduction for each Mystic Ally you have out. Your Mystic Allies no longer take damage."}], "6": [{"format": "Gain the passive abilities of the five runed Mystic Allies at all times. Attacking enemies creates your chosen Mystic Ally that lasts 15 seconds, up to 10 Mystic Allies. The damage of your Mystic Allies is increased by 900%% for each Mystic Ally you have out."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('sunwuko','Monkey King''s Garb','{"2": [{"format": "Your damage taken is reduced by 50%% while Sweeping Wind is active."}], "4": [{"format": "Every second Sweeping Wind spawns a decoy next to the last enemy you hit that taunts nearby enemies and then explodes for 1000%% weapon damage for each stack of Sweeping Wind you have."}], "6": [{"format": "Lashing Tail Kick, Tempest Rush, and Wave of Light have their damage increased by 1500%% for each stack of Sweeping Wind you have."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('storms','Raiment of a Thousand Storms','{"2": [{"format": "Your Spirit Generators have 25%% increased attack speed and 400%% increased damage."}], "4": [{"format": "Dashing Strike now spends 25 Spirit, but refunds a Charge when it does."}], "6": [{"format": "Your Spirit Generators increase the weapon damage of Dashing Strike to 60000%% for 6 seconds and Dashing Strike increases the damage of your Spirit Generators by 14000%% for 6 seconds."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('akkhan','Armor of Akkhan','{"2": [{"format": "Judgment has no cooldown and gains the effect of every rune."}], "4": [{"format": "Attacks from Phalanx Avatars reduce the cooldown of Akarat''s Champion by 0.5 seconds, and also apply Condemn when attacking enemies that are affected by Judgment."}], "6": [{"format": "While Akarat''s Champion is active, you deal 1500%% increased damage and take 50%% less damage."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('roland','Roland''s Legacy','{"2": [{"format": "Every use of Shield Bash and Sweep Attack reduces the cooldown of your Laws and Defensive Skills by 1 second."}], "4": [{"format": "Increase the damage of Shield Bash and Sweep Attack by 40000%%."}], "6": [{"format": "Every use of Shield Bash or Sweep Attack that hits an enemy grants 75%% increased Attack Speed and 15%% damage reduction for 8 seconds. This effect stacks up to 5 times."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('magnumopus','Delsere''s Magnum Opus','{"2": [{"format": "Hitting an enemy with Arcane Orb, Energy Twister, Magic Missile, Shock Pulse, Spectral Blade, Electrocute, or Arcane Torrent also casts Slow Time at them. This effect will not trigger if the target is already inside a Slow Time bubble. The cooldown of Teleport will reset while you''re inside bubbles generated from this set or cast by you."}], "4": [{"format": "You take 75%% reduced damage while you have a Slow Time active. Allies inside your Slow Time gain half benefit."}], "6": [{"format": "Enemies affected by your Slow Time and for 5 seconds after exiting take 20000%% increased damage from your Arcane Orb, Energy Twister, Magic Missile, Shock Pulse, Spectral Blade, Electrocute, and Arcane Torrent abilities."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('unhallowed','Unhallowed Essence','{"2": [{"format": "Your generators generate 2 additional Hatred and 1 Discipline."}], "4": [{"format": "Gain 60%% damage reduction and deal 60%% increased damage for 8 seconds if no enemy is within 10 yards of you."}], "6": [{"format": "Your generators, Multishot and Vengeance deal 1700%% increased damage for every point of Discipline you have."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('wastes','Wrath of the Wastes','{"2": [{"format": "Increase the damage per second of Rend by 500%% and its duration to 15 seconds."}], "4": [{"format": "During Whirlwind and for 3 seconds after, you gain 50%% damage reduction and your applied Rends deal triple damage."}], "6": [{"format": "Whirlwind gains the effect of the Dust Devils rune and all Whirlwind and Rend damage is increased by 10000%%."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('light','Seeker of the Light','{"2": [{"format": "Every use of Blessed Hammer that hits an enemy reduces the cooldown of Falling Sword and Provoke by 1 second."}], "4": [{"format": "You take 50%% less damage for 8 seconds after landing with Falling Sword."}], "6": [{"format": "Increase the damage of Blessed Hammer by 15000%% and Falling Sword by 1000%%."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('uliana','Uliana''s Stratagem','{"2": [{"format": "Every third hit of your Spirit Generators applies Exploding Palm."}], "4": [{"format": "Your Seven-Sided Strike deals 777%% its total damage with each hit. All damage taken is reduced by 77%% for 7 seconds after applying Exploding Palm to an enemy."}], "6": [{"format": "Increase the damage of your Exploding Palm by 12500%% and your Seven-Sided Strike detonates your Exploding Palm."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('arachyr','Spirit of Arachyr','{"2": [{"format": "Summon a permanent Spider Queen connected to you by an infested thread. Enemies caught in the thread are infested. Corpse Spider attacks against infested enemies inflict the same damage to all infested enemies. The Spider Queen is commanded to move to where you cast your Corpse Spiders. Corpse Spiders now spawns with health."}], "4": [{"format": "The Spider Queen now leaves behind webs that lasts for 15 seconds and Slows enemies. Infested enemies remain infested while on the web. You take 75%% reduced damage while in the web and for 4 seconds after."}], "6": [{"format": "The damage of your creature skills is increased by 11500%%. Creature skills are Corpse Spiders, Plague of Toads, Firebats, Locust Swarm, Hex, and Piranhas."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('norvald','Norvald''s Fervor','{"2": [{"format": "Increases the duration of Steed Charge by 2 seconds. In addition, killing an enemy reduces the cooldown of Steed Charge by 1 second."}, {"format": "Gain 200%% increased damage while using Steed Charge and for 5 seconds after it ends."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('rathma','Bones of Rathma','{"2": [{"format": "Your permanent minions reduce the cooldown of Army of the Dead by 0.50 seconds each time they deal damage. Your skeletal warriors spawn faster, and your revived minions no longer expire."}], "4": [{"format": "Your minions no longer take damage. You gain 1%% damage reduction for 15 seconds each time one of your minions deal damage. Max 75 stacks."}], "6": [{"format": "Each permanent active minion increases the damage of Army of the Dead by 1750%%, up to 31500%%."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('trangoul','Trag''Oul''s Avatar','{"2": [{"format": "Blood Rush and Siphon Blood gain the effect of every rune. Your Life-spending abilities no longer cost Essence."}], "4": [{"format": "While at full Life, your healing from skills is added to your maximum Life for 45 seconds, up to 300%% more."}], "6": [{"format": "Your Life-spending abilities deal 6250%% increased damage and your healing from skills is increased by 100%%."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('inarius','Grace of Inarius','{"2": [{"format": "Bone Armor damage is increased by 1000%%."}], "4": [{"format": "Bone Armor grants an additional 3%% damage reduction per enemy hit."}], "6": [{"format": "Bone Armor also activates a swirling tornado of bone, damaging nearby enemies for 1000%% weapon damage and increasing the damage they take from the Necromancer by 19000%%."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('pestilence','Pestilence Master''s Shroud','{"2": [{"format": "Each corpse you consume fires a Corpse Lance at a nearby enemy."}], "4": [{"format": "Each enemy you hit with Bone Spear, Corpse Lance and Corpse Explosion reduces your damage taken by 3%%, up to a maximum of 75%%. Lasts 15 seconds."}], "6": [{"format": "Each corpse you consume grants you an Empowered Bone Spear charge that increases the damage of your next Bone Spear by 6000%%. In addition, Corpse Lance and Corpse Explosion damage is increased by 6000%%."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('jesseth','Jesseth Arms','{"2": [{"format": "When the target of your Command Skeletons dies, your skeletons are automatically commanded to attack a nearby target."}, {"format": "While your skeletons are commanded to attack a target, you deal 400%% increased damage."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('aughild_v2','Aughild''s Authority','{"2": [{"stat": "dmgred", "value": [15]}, {"stat": "dmgmul", "value": [30]}], "3": [{"stat": "edef", "value": [30]}, {"stat": "edmg", "value": [30]}]}');
INSERT INTO `dc_set_tooltip` VALUES ('cain_v2','Cain''s Destiny','{"2": [{"stat": "ias", "value": [8]}, {"stat": "expmul", "value": [50]}], "3": [{"format": "When a Greater Rift Keystone drops, there is a 25%% chance for an extra one to drop. (Emanates)", "follower": true}]}');
INSERT INTO `dc_set_tooltip` VALUES ('crimson_v2','Captain Crimson''s Trimmings','{"2": [{"stat": "regen", "value": [6000]}, {"stat": "cdr", "value": [20]}, {"stat": "rcr", "value": [20]}], "3": [{"format": "Damage dealt is increased by your percentage of cooldown reduction."}, {"format": "Damage taken is reduced by your percentage of cost reduction."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('valor','Aegis of Valor','{"2": [{"format": "Attacking with Fists of the Heavens empowers you, allowing Heaven''s Fury to deal 125%% increased damage for 5 seconds. Stacks up to 3 times."}], "4": [{"format": "Hitting with Fist of the Heavens returns 5 Wrath and reduces damage taken by 1%% for 10 seconds. Stacks up to 50 times."}], "6": [{"format": "Increase the damage of Fist of the Heavens and Heaven''s Fury by 15000%%."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('justice','Patterns of Justice','{"2": [{"format": "Sweeping Wind gains the effect of every rune, and movement speed is increased by 5%% for each stack of Sweeping Wind."}], "4": [{"format": "Attacking with Tempest Rush reduces your damage taken by 50%% and increases Spirit Regeneration by 50."}], "6": [{"format": "Hitting with Tempest Rush while Sweeping Wind is active increases the size of Sweeping Wind and also increases all damage dealt by 20000%%."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('savages','Horde of the Ninety Savages','{"2": [{"format": "Double the effectiveness of shouts. You deal double damage to Feared, Frozen, or Stunned enemies."}], "4": [{"format": "Each Frenzy stack reduces damage taken by 6%%. Frenzy lasts twice as long."}], "6": [{"format": "Frenzy deals 2000%% increased damage per stack."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('mundunugu','Mundunugu''s Regalia','{"2": [{"format": "Big Bad Voodoo now follows you and lasts twice as long."}], "4": [{"format": "Gain 60%% damage reduction for 30 seconds when you enter the spirit realm."}], "6": [{"format": "Spirit Barrage deals 17,500%% increased damage plus an additional %% equal to 5 times your Mana Regeneration/Second."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('typhon','The Typhon''s Veil','{"2": [{"format": "Double the duration of Hydras and increase the number of heads on multi-headed Hydras by two."}], "4": [{"format": "Damage taken is reduced by 8%% for each Hydra head alive. Each time you take damage, a head dies. A head cannot die more than once every 2 seconds."}], "6": [{"format": "Hydras deal 4000%% increased damage for each Hydra head alive."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('dreadlands','Gears of Dreadlands','{"2": [{"format": "Gain 4 seconds of Momentum when attacking with a Primary skill, at a maximum duration of 20 seconds. This duration begins counting down after a delay of 5 seconds after each application. Your Primary skills deal 10%% increased damage per second of Momentum."}], "4": [{"format": "Strafing against enemies will automatically shoot your last used primary skill, and also give 60%% damage reduction while strafing and for 5 seconds after. While Strafing, you gain 8%% increased movement speed for each second of Momentum."}], "6": [{"format": "Your primary skills deal 27500%% increased damage."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('masquerade','Masquerade of the Burning Carnival','{"2": [{"format": "Simulacrums no longer take damage, gains all runes, and its cooldown is refreshed when you die."}], "4": [{"format": "While you have a Simulacrum, damage is reduced by 50%%. Damage you take is split with your Simulacrums as well."}], "6": [{"format": "Bone Spear cast by you and your Simulacrums deals 5500%% increased damage. Simulacrums gain triple this bonus."}]}');
INSERT INTO `dc_set_tooltip` VALUES ('guardian_p74','Guardian''s Jeopardy','{"2": [{"format": "Your melee damage reduction is increased by 1%% per 1000 base Vitality from equipped items."}, {"format": "Your missile damage reduction is increased by 1%% per 1000 base Strength, Dexterity, or Intelligence from equipped items depending on your class."}], "3": [{"format": "You gain an additional 100%% of your base Strength, Dexterity, Intelligence, and Vitality attributes from equipped items."}]}');
DROP TABLE IF EXISTS `dc_set_bonus`;
CREATE TABLE `dc_set_bonus` (set_id VARCHAR(80),pieces INT,body LONGTEXT,PRIMARY KEY(set_id,pieces)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `dc_set_bonus` VALUES ('chantodo',2,'Every second while in Archon form you expel a Wave of Destruction, dealing 4000%% weapon damage to enemies within 30 yards. This damage scales with attack speed.
Every time you hit with an attack while not in Archon form, 4000%% weapon damage is added to the Wave of Destruction, stacking up to 20 times.');
INSERT INTO `dc_set_bonus` VALUES ('danetta',2,'Vault costs 8 Hatred instead of Discipline.
Vault deals 800%% increased damage.');
INSERT INTO `dc_set_bonus` VALUES ('blackthorne',2,'
');
INSERT INTO `dc_set_bonus` VALUES ('blackthorne',3,'
');
INSERT INTO `dc_set_bonus` VALUES ('blackthorne',4,'You are immune to Desecrator, Molten, and Plagued monster ground effects.');
INSERT INTO `dc_set_bonus` VALUES ('bulkathos',2,'
During Whirlwind gain 45%% increased Attack Speed and Movement Speed.');
INSERT INTO `dc_set_bonus` VALUES ('endlesswalk',2,'While moving, damage taken is reduced by up to 50%%.
While standing still, damage dealt is increased by up to 100%%.');
INSERT INTO `dc_set_bonus` VALUES ('nightmares',2,'While this is your only Item Set bonus every Ancient item you have equipped increases your damage dealt by 750%% and reduces your damage taken by 4%%.');
INSERT INTO `dc_set_bonus` VALUES ('manajuma',2,'Your Hex - Angry Chicken explosion damage is increased by 2000%% and slain enemies trigger an additional explosion.
While you are an angry chicken, you spawn a chicken every half second that seeks enemies and deals 100%% of your Angry Chicken explosion damage.
Your Hex - Angry Chicken lasts 15 seconds and movement speed is increased by an additional 100%% while gaining 75%% damage reduction. These bonuses lasts while you are a chicken and for 5 seconds after.');
INSERT INTO `dc_set_bonus` VALUES ('shenlong',2,'The damage of your Spirit Generators is increased by 2%% for each point of Spirit you have.
When reaching maximum Spirit, all damage is increased by 350%%, but you no longer passively regenerate Spirit and 65 Spirit is drained every second until you run out of Spirit.');
INSERT INTO `dc_set_bonus` VALUES ('bastionsofwill',2,'When you hit with a resource-generating attack or primary skill, deal 50%% increased damage for 5 seconds.
When you hit with a resource-spending attack, deal 50%% increased damage for 5 seconds.');
INSERT INTO `dc_set_bonus` VALUES ('istvan',2,'Every time you spend primary resource, gain 6%% increased Attack Speed, Damage, and Armor for 5 seconds. This effect stacks up to 5 times.');
INSERT INTO `dc_set_bonus` VALUES ('invoker',2,'Your Thorns damage now hits all enemies in a 15 yard radius around you. Each time you hit an enemy with Punish, Slash, or block an attack your Thorns is increased by 90%% for 2 seconds. This effect stacks up to 10 times.');
INSERT INTO `dc_set_bonus` VALUES ('invoker',4,'You take 50%% less damage for 20 seconds after damaging an enemy with Bombardment.');
INSERT INTO `dc_set_bonus` VALUES ('invoker',6,'The attack speed of Punish and Slash are increased by 100%% and deal 67500%% of your Thorns damage.');
INSERT INTO `dc_set_bonus` VALUES ('krelm',2,'');
INSERT INTO `dc_set_bonus` VALUES ('asheara',2,'');
INSERT INTO `dc_set_bonus` VALUES ('asheara',3,'');
INSERT INTO `dc_set_bonus` VALUES ('asheara',4,'Attacks cause your followers to occasionally come to your aid.');
