INSERT INTO `dc_set_bonus` VALUES ('sage',3,'Double the amount of Death''s Breath that drop. (Emanates)');
INSERT INTO `dc_set_bonus` VALUES ('talrasha',2,'Damaging enemies with Arcane, Cold, Fire or Lightning will grant immunity to that element and cause a Meteor of the same damage type to fall from the sky. This only occurs if the Wizard has Meteor on their action bar, and the same meteor cannot happen twice in a row.');
INSERT INTO `dc_set_bonus` VALUES ('talrasha',4,'Arcane, Cold, Fire, and Lightning attacks each increase all of your resistances by 100%% for 8 seconds. Attacking with Meteor reduces the cooldown of Teleport by 1 second.');
INSERT INTO `dc_set_bonus` VALUES ('talrasha',6,'Attacks increase your damage by 1000%% for 8 seconds. Arcane, Cold, Fire, and Lightning attacks each add one stack. At 4 stacks, each different elemental attack extends the duration by 2 seconds, up to a maximum of 8 seconds.');
INSERT INTO `dc_set_bonus` VALUES ('vyr',2,'Archon gains the effect of every rune.');
INSERT INTO `dc_set_bonus` VALUES ('vyr',4,'Archon stacks also increase your Attack Speed, Armor, and Resistances by 1%%.');
INSERT INTO `dc_set_bonus` VALUES ('vyr',6,'You gain 1 Archon stack when you hit with an Archon ability and Archon stacks also reduce damage taken by 0.15%% and have their damage bonus increased to 100%%.');
INSERT INTO `dc_set_bonus` VALUES ('firebird',2,'Disintegrate Ignites enemies, causing them to take 3000%% weapon damage per second until they die. When you die, a meteor falls from the sky and revives you. This effect has a 60 second cooldown.');
INSERT INTO `dc_set_bonus` VALUES ('firebird',4,'Casting Disintegrate adds Combustion stacks that reduce the cooldown of Teleport by 2%% per stack. Stacks up to 50 times. You gain 80%% damage reduction while maintaining Combustion stacks.');
INSERT INTO `dc_set_bonus` VALUES ('firebird',6,'You gain 5000%% increased damage while Ignite is applied to a target. Hitting an Ignited enemy with a non-channeling fire spell deals Ignite damage multiplied by Combustion stacks. Pets cannot trigger this effect.');
INSERT INTO `dc_set_bonus` VALUES ('natalya',2,'Spike Trap deals 100%% increased damage to enemies affected by Caltrops. Spike Trap now instantly refreshes charges on use, no longer costs resources, and each detonation restores 2 Discipline.');
INSERT INTO `dc_set_bonus` VALUES ('natalya',4,'Spike Trap explosions will blast affected enemies towards the nearest set Caltrops. Laying a Spike Trap grants 75%% damage reduction. The duration of this bonus is always equal to the number of already laid traps in seconds.');
INSERT INTO `dc_set_bonus` VALUES ('natalya',6,'Spike Trap deals 10000%% increased damage, and each consecutive explosion from the detonated chain reaction will deal 25%% more damage than the previous blast.');
INSERT INTO `dc_set_bonus` VALUES ('shadow',2,'While equipped with a melee weapon, the damage of your Bolas, Chakram, Fan of Knives, and Impale is increased by 6000%%.');
INSERT INTO `dc_set_bonus` VALUES ('shadow',4,'Shadow Power gains the effect of every rune and lasts forever.');
INSERT INTO `dc_set_bonus` VALUES ('shadow',6,'Impale deals an additional 120000%% weapon damage to the first enemy hit, and 40000%% to subsequent enemies.');
INSERT INTO `dc_set_bonus` VALUES ('marauder',2,'Companion calls all companion types to your side.');
INSERT INTO `dc_set_bonus` VALUES ('marauder',4,'Sentries cast Elemental Arrow, Chakram, Impale, Multishot, and Cluster Arrow when you do, as well as automatically cast your equipped Hatred spenders.');
INSERT INTO `dc_set_bonus` VALUES ('marauder',6,'Your primary skills, Elemental Arrow, Chakram, Impale, Multishot, Cluster Arrow, Companions, Vengeance and Sentries deal 9500%% increased damage for every active Sentry.');
INSERT INTO `dc_set_bonus` VALUES ('zunimassa',2,'Your Fetish Army lasts until they die and the cooldown of your Fetish Army is reduced by 80%.');
INSERT INTO `dc_set_bonus` VALUES ('zunimassa',4,'You and your pets take 3% less damage for every Fetish you have alive.');
INSERT INTO `dc_set_bonus` VALUES ('zunimassa',6,'Enemies hit by your Mana spenders take 13000%% more damage from your pets for 8 seconds.');
INSERT INTO `dc_set_bonus` VALUES ('helltooth',2,'Enemies hit by your primary skills, Acid Cloud, Firebats, Zombie Charger, Zombie Dogs, Gargantuan, Grasp of the Dead, Piranhas, or Wall of Death are afflicted by Necrosis, becoming Slowed and taking 3000%% weapon damage every second for 10 seconds.');
INSERT INTO `dc_set_bonus` VALUES ('helltooth',4,'After applying Necrosis to an enemy, you take 60%% reduced damage for 10 seconds.');
INSERT INTO `dc_set_bonus` VALUES ('helltooth',6,'After casting Wall of Death, gain 37500%% increased damage for 15 seconds to your primary skills, Acid Cloud, Firebats, Zombie Charger, Zombie Dogs, Gargantuan, Grasp of the Dead, Piranhas, and Wall of Death.');
INSERT INTO `dc_set_bonus` VALUES ('jadeharvester',2,'When Haunt lands on an enemy already affected by Haunt, it instantly deals 3500 seconds worth of Haunt damage.');
INSERT INTO `dc_set_bonus` VALUES ('jadeharvester',4,'Soul Harvest gains the effect of every rune and has its cooldown reduced by 1 second every time you cast Haunt or Locust Swarm.');
INSERT INTO `dc_set_bonus` VALUES ('jadeharvester',6,'Soul Harvest reduces damage taken by 50%% for 12 seconds and consumes your damage over time effects on enemies, instantly dealing 26,000 seconds worth of remaining damage.');
INSERT INTO `dc_set_bonus` VALUES ('immortalking',2,'Call of the Ancients last until they die.');
INSERT INTO `dc_set_bonus` VALUES ('immortalking',4,'Reduce the cooldown of Wrath of the Berserker and Call of the Ancients by 3 seconds for every 10 Fury you spend with an attack.');
INSERT INTO `dc_set_bonus` VALUES ('immortalking',6,'While both Wrath of the Berserker and Call of the Ancients are active, you deal 4000%% increased damage.');
INSERT INTO `dc_set_bonus` VALUES ('earth',2,'Reduce the cooldown of Earthquake, Avalanche, Leap, and Ground Stomp by 1 second for every 30 Fury you spend with an attack.');
INSERT INTO `dc_set_bonus` VALUES ('earth',4,'Leap causes an Earthquake when you land. Additionally, Leap gains the effect of the Iron Impact rune and the rune''s effect and duration are increased by 150%%.');
INSERT INTO `dc_set_bonus` VALUES ('earth',6,'Increase the damage of Earthquake, Avalanche, Leap, Ground Stomp, Ancient Spear and Seismic Slam by 37500%%.');
INSERT INTO `dc_set_bonus` VALUES ('raekor',2,'Furious Charge refunds a charge if it hits only 1 enemy.');
INSERT INTO `dc_set_bonus` VALUES ('raekor',4,'Furious Charge gains the effect of every rune and deals 1000%% increased damage. For every 1%% Life you are missing, the damage of your Ancient Spear is increased by 2%%.');
INSERT INTO `dc_set_bonus` VALUES ('raekor',6,'Hitting enemies with Furious Charge or Weapon Throw increases the damage of your next Ancient Spear by 2500%% and causes it to release multiple spears from its target. This effect stacks and each spear throw consumes a maximum of 5 stacks.');
INSERT INTO `dc_set_bonus` VALUES ('inna',2,'Increase the passive effect of your Mystic Ally and the base passive effect of your Mantra by 100%%.');
INSERT INTO `dc_set_bonus` VALUES ('inna',4,'Gain the base effect of all four Mantras at all times. You gain 5% damage reduction for each Mystic Ally you have out. Your Mystic Allies no longer take damage.');
INSERT INTO `dc_set_bonus` VALUES ('inna',6,'Gain the passive abilities of the five runed Mystic Allies at all times. Attacking enemies creates your chosen Mystic Ally that lasts 15 seconds, up to 10 Mystic Allies. The damage of your Mystic Allies is increased by 900%% for each Mystic Ally you have out.');
INSERT INTO `dc_set_bonus` VALUES ('sunwuko',2,'Your damage taken is reduced by 50%% while Sweeping Wind is active.');
INSERT INTO `dc_set_bonus` VALUES ('sunwuko',4,'Every second Sweeping Wind spawns a decoy next to the last enemy you hit that taunts nearby enemies and then explodes for 1000%% weapon damage for each stack of Sweeping Wind you have.');
INSERT INTO `dc_set_bonus` VALUES ('sunwuko',6,'Lashing Tail Kick, Tempest Rush, and Wave of Light have their damage increased by 1500%% for each stack of Sweeping Wind you have.');
INSERT INTO `dc_set_bonus` VALUES ('storms',2,'Your Spirit Generators have 25%% increased attack speed and 400%% increased damage.');
INSERT INTO `dc_set_bonus` VALUES ('storms',4,'Dashing Strike now spends 25 Spirit, but refunds a Charge when it does.');
INSERT INTO `dc_set_bonus` VALUES ('storms',6,'Your Spirit Generators increase the weapon damage of Dashing Strike to 60000%% for 6 seconds and Dashing Strike increases the damage of your Spirit Generators by 14000%% for 6 seconds.');
INSERT INTO `dc_set_bonus` VALUES ('akkhan',2,'Judgment has no cooldown and gains the effect of every rune.');
INSERT INTO `dc_set_bonus` VALUES ('akkhan',4,'Attacks from Phalanx Avatars reduce the cooldown of Akarat''s Champion by 0.5 seconds, and also apply Condemn when attacking enemies that are affected by Judgment.');
INSERT INTO `dc_set_bonus` VALUES ('akkhan',6,'While Akarat''s Champion is active, you deal 1500%% increased damage and take 50%% less damage.');
INSERT INTO `dc_set_bonus` VALUES ('roland',2,'Every use of Shield Bash and Sweep Attack reduces the cooldown of your Laws and Defensive Skills by 1 second.');
INSERT INTO `dc_set_bonus` VALUES ('roland',4,'Increase the damage of Shield Bash and Sweep Attack by 40000%%.');
INSERT INTO `dc_set_bonus` VALUES ('roland',6,'Every use of Shield Bash or Sweep Attack that hits an enemy grants 75%% increased Attack Speed and 15%% damage reduction for 8 seconds. This effect stacks up to 5 times.');
INSERT INTO `dc_set_bonus` VALUES ('magnumopus',2,'Hitting an enemy with Arcane Orb, Energy Twister, Magic Missile, Shock Pulse, Spectral Blade, Electrocute, or Arcane Torrent also casts Slow Time at them. This effect will not trigger if the target is already inside a Slow Time bubble. The cooldown of Teleport will reset while you''re inside bubbles generated from this set or cast by you.');
INSERT INTO `dc_set_bonus` VALUES ('magnumopus',4,'You take 75%% reduced damage while you have a Slow Time active. Allies inside your Slow Time gain half benefit.');
INSERT INTO `dc_set_bonus` VALUES ('magnumopus',6,'Enemies affected by your Slow Time and for 5 seconds after exiting take 20000%% increased damage from your Arcane Orb, Energy Twister, Magic Missile, Shock Pulse, Spectral Blade, Electrocute, and Arcane Torrent abilities.');
INSERT INTO `dc_set_bonus` VALUES ('unhallowed',2,'Your generators generate 2 additional Hatred and 1 Discipline.');
INSERT INTO `dc_set_bonus` VALUES ('unhallowed',4,'Gain 60%% damage reduction and deal 60%% increased damage for 8 seconds if no enemy is within 10 yards of you.');
INSERT INTO `dc_set_bonus` VALUES ('unhallowed',6,'Your generators, Multishot and Vengeance deal 1700%% increased damage for every point of Discipline you have.');
INSERT INTO `dc_set_bonus` VALUES ('wastes',2,'Increase the damage per second of Rend by 500%% and its duration to 15 seconds.');
INSERT INTO `dc_set_bonus` VALUES ('wastes',4,'During Whirlwind and for 3 seconds after, you gain 50%% damage reduction and your applied Rends deal triple damage.');
INSERT INTO `dc_set_bonus` VALUES ('wastes',6,'Whirlwind gains the effect of the Dust Devils rune and all Whirlwind and Rend damage is increased by 10000%%.');
INSERT INTO `dc_set_bonus` VALUES ('light',2,'Every use of Blessed Hammer that hits an enemy reduces the cooldown of Falling Sword and Provoke by 1 second.');
INSERT INTO `dc_set_bonus` VALUES ('light',4,'You take 50%% less damage for 8 seconds after landing with Falling Sword.');
INSERT INTO `dc_set_bonus` VALUES ('light',6,'Increase the damage of Blessed Hammer by 15000%% and Falling Sword by 1000%%.');
INSERT INTO `dc_set_bonus` VALUES ('uliana',2,'Every third hit of your Spirit Generators applies Exploding Palm.');
INSERT INTO `dc_set_bonus` VALUES ('uliana',4,'Your Seven-Sided Strike deals 777%% its total damage with each hit. All damage taken is reduced by 77%% for 7 seconds after applying Exploding Palm to an enemy.');
INSERT INTO `dc_set_bonus` VALUES ('uliana',6,'Increase the damage of your Exploding Palm by 12500%% and your Seven-Sided Strike detonates your Exploding Palm.');
INSERT INTO `dc_set_bonus` VALUES ('arachyr',2,'Summon a permanent Spider Queen connected to you by an infested thread. Enemies caught in the thread are infested. Corpse Spider attacks against infested enemies inflict the same damage to all infested enemies. The Spider Queen is commanded to move to where you cast your Corpse Spiders. Corpse Spiders now spawns with health.');
INSERT INTO `dc_set_bonus` VALUES ('arachyr',4,'The Spider Queen now leaves behind webs that lasts for 15 seconds and Slows enemies. Infested enemies remain infested while on the web. You take 75%% reduced damage while in the web and for 4 seconds after.');
INSERT INTO `dc_set_bonus` VALUES ('arachyr',6,'The damage of your creature skills is increased by 11500%%. Creature skills are Corpse Spiders, Plague of Toads, Firebats, Locust Swarm, Hex, and Piranhas.');
INSERT INTO `dc_set_bonus` VALUES ('norvald',2,'Increases the duration of Steed Charge by 2 seconds. In addition, killing an enemy reduces the cooldown of Steed Charge by 1 second.
Gain 200%% increased damage while using Steed Charge and for 5 seconds after it ends.');
INSERT INTO `dc_set_bonus` VALUES ('rathma',2,'Your permanent minions reduce the cooldown of Army of the Dead by 0.50 seconds each time they deal damage. Your skeletal warriors spawn faster, and your revived minions no longer expire.');
INSERT INTO `dc_set_bonus` VALUES ('rathma',4,'Your minions no longer take damage. You gain 1%% damage reduction for 15 seconds each time one of your minions deal damage. Max 75 stacks.');
INSERT INTO `dc_set_bonus` VALUES ('rathma',6,'Each permanent active minion increases the damage of Army of the Dead by 1750%%, up to 31500%%.');
INSERT INTO `dc_set_bonus` VALUES ('trangoul',2,'Blood Rush and Siphon Blood gain the effect of every rune. Your Life-spending abilities no longer cost Essence.');
INSERT INTO `dc_set_bonus` VALUES ('trangoul',4,'While at full Life, your healing from skills is added to your maximum Life for 45 seconds, up to 300%% more.');
INSERT INTO `dc_set_bonus` VALUES ('trangoul',6,'Your Life-spending abilities deal 6250%% increased damage and your healing from skills is increased by 100%%.');
INSERT INTO `dc_set_bonus` VALUES ('inarius',2,'Bone Armor damage is increased by 1000%%.');
INSERT INTO `dc_set_bonus` VALUES ('inarius',4,'Bone Armor grants an additional 3%% damage reduction per enemy hit.');
INSERT INTO `dc_set_bonus` VALUES ('inarius',6,'Bone Armor also activates a swirling tornado of bone, damaging nearby enemies for 1000%% weapon damage and increasing the damage they take from the Necromancer by 19000%%.');
INSERT INTO `dc_set_bonus` VALUES ('pestilence',2,'Each corpse you consume fires a Corpse Lance at a nearby enemy.');
INSERT INTO `dc_set_bonus` VALUES ('pestilence',4,'Each enemy you hit with Bone Spear, Corpse Lance and Corpse Explosion reduces your damage taken by 3%%, up to a maximum of 75%%. Lasts 15 seconds.');
INSERT INTO `dc_set_bonus` VALUES ('pestilence',6,'Each corpse you consume grants you an Empowered Bone Spear charge that increases the damage of your next Bone Spear by 6000%%. In addition, Corpse Lance and Corpse Explosion damage is increased by 6000%%.');
INSERT INTO `dc_set_bonus` VALUES ('jesseth',2,'When the target of your Command Skeletons dies, your skeletons are automatically commanded to attack a nearby target.
While your skeletons are commanded to attack a target, you deal 400%% increased damage.');
INSERT INTO `dc_set_bonus` VALUES ('aughild_v2',2,'
');
INSERT INTO `dc_set_bonus` VALUES ('aughild_v2',3,'
');
INSERT INTO `dc_set_bonus` VALUES ('cain_v2',2,'
');
INSERT INTO `dc_set_bonus` VALUES ('cain_v2',3,'When a Greater Rift Keystone drops, there is a 25%% chance for an extra one to drop. (Emanates)');
INSERT INTO `dc_set_bonus` VALUES ('crimson_v2',2,'

');
INSERT INTO `dc_set_bonus` VALUES ('crimson_v2',3,'Damage dealt is increased by your percentage of cooldown reduction.
Damage taken is reduced by your percentage of cost reduction.');
INSERT INTO `dc_set_bonus` VALUES ('valor',2,'Attacking with Fists of the Heavens empowers you, allowing Heaven''s Fury to deal 125%% increased damage for 5 seconds. Stacks up to 3 times.');
INSERT INTO `dc_set_bonus` VALUES ('valor',4,'Hitting with Fist of the Heavens returns 5 Wrath and reduces damage taken by 1%% for 10 seconds. Stacks up to 50 times.');
INSERT INTO `dc_set_bonus` VALUES ('valor',6,'Increase the damage of Fist of the Heavens and Heaven''s Fury by 15000%%.');
INSERT INTO `dc_set_bonus` VALUES ('justice',2,'Sweeping Wind gains the effect of every rune, and movement speed is increased by 5%% for each stack of Sweeping Wind.');
INSERT INTO `dc_set_bonus` VALUES ('justice',4,'Attacking with Tempest Rush reduces your damage taken by 50%% and increases Spirit Regeneration by 50.');
INSERT INTO `dc_set_bonus` VALUES ('justice',6,'Hitting with Tempest Rush while Sweeping Wind is active increases the size of Sweeping Wind and also increases all damage dealt by 20000%%.');
INSERT INTO `dc_set_bonus` VALUES ('savages',2,'Double the effectiveness of shouts. You deal double damage to Feared, Frozen, or Stunned enemies.');
INSERT INTO `dc_set_bonus` VALUES ('savages',4,'Each Frenzy stack reduces damage taken by 6%%. Frenzy lasts twice as long.');
INSERT INTO `dc_set_bonus` VALUES ('savages',6,'Frenzy deals 2000%% increased damage per stack.');
INSERT INTO `dc_set_bonus` VALUES ('mundunugu',2,'Big Bad Voodoo now follows you and lasts twice as long.');
INSERT INTO `dc_set_bonus` VALUES ('mundunugu',4,'Gain 60%% damage reduction for 30 seconds when you enter the spirit realm.');
INSERT INTO `dc_set_bonus` VALUES ('mundunugu',6,'Spirit Barrage deals 17,500%% increased damage plus an additional %% equal to 5 times your Mana Regeneration/Second.');
INSERT INTO `dc_set_bonus` VALUES ('typhon',2,'Double the duration of Hydras and increase the number of heads on multi-headed Hydras by two.');
INSERT INTO `dc_set_bonus` VALUES ('typhon',4,'Damage taken is reduced by 8%% for each Hydra head alive. Each time you take damage, a head dies. A head cannot die more than once every 2 seconds.');
INSERT INTO `dc_set_bonus` VALUES ('typhon',6,'Hydras deal 4000%% increased damage for each Hydra head alive.');
INSERT INTO `dc_set_bonus` VALUES ('dreadlands',2,'Gain 4 seconds of Momentum when attacking with a Primary skill, at a maximum duration of 20 seconds. This duration begins counting down after a delay of 5 seconds after each application. Your Primary skills deal 10%% increased damage per second of Momentum.');
INSERT INTO `dc_set_bonus` VALUES ('dreadlands',4,'Strafing against enemies will automatically shoot your last used primary skill, and also give 60%% damage reduction while strafing and for 5 seconds after. While Strafing, you gain 8%% increased movement speed for each second of Momentum.');
INSERT INTO `dc_set_bonus` VALUES ('dreadlands',6,'Your primary skills deal 27500%% increased damage.');
INSERT INTO `dc_set_bonus` VALUES ('masquerade',2,'Simulacrums no longer take damage, gains all runes, and its cooldown is refreshed when you die.');
INSERT INTO `dc_set_bonus` VALUES ('masquerade',4,'While you have a Simulacrum, damage is reduced by 50%%. Damage you take is split with your Simulacrums as well.');
INSERT INTO `dc_set_bonus` VALUES ('masquerade',6,'Bone Spear cast by you and your Simulacrums deals 5500%% increased damage. Simulacrums gain triple this bonus.');
INSERT INTO `dc_set_bonus` VALUES ('guardian_p74',2,'Your melee damage reduction is increased by 1%% per 1000 base Vitality from equipped items.
Your missile damage reduction is increased by 1%% per 1000 base Strength, Dexterity, or Intelligence from equipped items depending on your class.');
INSERT INTO `dc_set_bonus` VALUES ('guardian_p74',3,'You gain an additional 100%% of your base Strength, Dexterity, Intelligence, and Vitality attributes from equipped items.');
DROP TABLE IF EXISTS `dc_item_tooltip`;
CREATE TABLE `dc_item_tooltip` (d3_id VARCHAR(100) PRIMARY KEY,set_id VARCHAR(80),power_text LONGTEXT,flavour LONGTEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `dc_item_tooltip` VALUES ('Unique_Amulet_105_x1','','After earning a massacre bonus, 4–6 Skeletons are summoned to fight by your side for 10 seconds.','');
INSERT INTO `dc_item_tooltip` VALUES ('Unique_Mace_1H_101_x1','','After killing 10 enemies, you release a Poison Nova that deals 1050–1400% weapon damage as Poison to enemies within 30 yards.','');
INSERT INTO `dc_item_tooltip` VALUES ('Unique_Shoulder_103_x1','','When receiving fatal damage, there is a chance that you are instead restored to 25% of maximum Life and cause nearby enemies to flee in fear.','');
INSERT INTO `dc_item_tooltip` VALUES ('P3_Unique_Ring_107','','Reduces the number of items needed for set bonuses by 1 (to a minimum of 2).','');
INSERT INTO `dc_item_tooltip` VALUES ('Unique_Bracer_105_x1','','Chance on being hit to deal 1000% of your Thorns damage to nearby enemies.','');
INSERT INTO `dc_item_tooltip` VALUES ('Unique_Cloak_102_x1','','Enemy missiles sometimes pass through you harmlessly.','');
INSERT INTO `dc_item_tooltip` VALUES ('Unique_Shield_107_x1','','You take 45–60% less damage from blocked attacks.','');
INSERT INTO `dc_item_tooltip` VALUES ('Unique_Gloves_103_x1','','Shrine effects last for 10 minutes. (Emanates)','');
INSERT INTO `dc_item_tooltip` VALUES ('Unique_Boots_103_x1','','You may move unhindered through enemies.','');
INSERT INTO `dc_item_tooltip` VALUES ('Unique_Ring_108_x1','','Each time you pick up gold, increase your Gold and Health Pickup radius by 1 yard for 10 seconds, stacking up to 30 times. (Emanates)','');
INSERT INTO `dc_item_tooltip` VALUES ('Unique_Axe_2H_103_x1','','Killing enemies and destroying objects has a chance to grant 20% of your maximum primary resource.','');
INSERT INTO `dc_item_tooltip` VALUES ('Unique_Boots_102_x1','','Gain 10000 Life regeneration per Second for each second you stand still. This effect stacks up to 4 times.','');
INSERT INTO `dc_item_tooltip` VALUES ('Unique_Dagger_103_x1','','Gain 100% Critical Hit Chance against enemies at full health.','');
INSERT INTO `dc_item_tooltip` VALUES ('Unique_Amulet_106_x1','','Chance on hit to charm the enemy. While charmed, the enemy takes 35% increased damage.','');
